function archParse(text){
  var edges=[], nodes=[], seen={};
  var lines=String(text||'').split('\n');
  for(var i=0;i<lines.length;i++){
    var ln=lines[i].trim();
    if(!ln || ln.charAt(0)==='#') continue;
    var m=/^(.+?)\s*->\s*(.+)$/.exec(ln);
    if(!m) return { error:'第 '+(i+1)+' 行格式错误（应为 A -> B）', nodes:[], edges:[] };
    var a=m[1].trim(), b=m[2].trim();
    if(!a||!b) return { error:'第 '+(i+1)+' 行节点为空', nodes:[], edges:[] };
    if(!seen[a]){ seen[a]=1; nodes.push(a); }
    if(!seen[b]){ seen[b]=1; nodes.push(b); }
    edges.push([a,b]);
  }
  return { error:null, nodes:nodes, edges:edges };
}
function archLayers(nodes, edges){
  var indeg={}, adj={}, i;
  for(i=0;i<nodes.length;i++){ indeg[nodes[i]]=0; adj[nodes[i]]=[]; }
  for(i=0;i<edges.length;i++){ adj[edges[i][0]].push(edges[i][1]); indeg[edges[i][1]]++; }
  var depth={}, q=[], order=[];
  for(i=0;i<nodes.length;i++) if(indeg[nodes[i]]===0){ q.push(nodes[i]); depth[nodes[i]]=0; }
  while(q.length){
    var u=q.shift(); order.push(u);
    for(i=0;i<adj[u].length;i++){
      var v=adj[u][i];
      depth[v]=Math.max(depth[v]||0, depth[u]+1);
      if(--indeg[v]===0) q.push(v);
    }
  }
  if(order.length!==nodes.length) return { error:'检测到循环依赖，无法分层', layers:[] };
  var maxd=0; for(i=0;i<nodes.length;i++) maxd=Math.max(maxd, depth[nodes[i]]);
  var layers=[]; for(i=0;i<=maxd;i++) layers.push([]);
  for(i=0;i<nodes.length;i++) layers[depth[nodes[i]]].push(nodes[i]);
  return { error:null, layers:layers, depth:depth };
}
function archEsc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function archSvg(parsed){
  if(parsed.error) return '';
  var L=archLayers(parsed.nodes, parsed.edges);
  if(L.error) return '';
  var layers=L.layers, NW=150, NH=44, GX=40, GY=64, PAD=24;
  var maxCols=1, i, j;
  for(i=0;i<layers.length;i++) maxCols=Math.max(maxCols, layers[i].length);
  var W=PAD*2+maxCols*NW+(maxCols-1)*GX, H=PAD*2+layers.length*NH+(layers.length-1)*GY;
  var pos={};
  for(i=0;i<layers.length;i++){
    var row=layers[i], rw=row.length*NW+(row.length-1)*GX, x0=(W-rw)/2;
    for(j=0;j<row.length;j++) pos[row[j]]={ x:x0+j*(NW+GX), y:PAD+i*(NH+GY) };
  }
  var cols=['#5E6AD2','#22D3EE','#10B981','#A78BFA','#F5A623'];
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">';
  s+='<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>';
  s+='<defs><marker id="ah" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L7,3 L0,6 Z" fill="#71717A"/></marker></defs>';
  for(i=0;i<parsed.edges.length;i++){
    var a=pos[parsed.edges[i][0]], b=pos[parsed.edges[i][1]];
    s+='<path d="M'+(a.x+NW/2)+','+(a.y+NH)+' C'+(a.x+NW/2)+','+(a.y+NH+GY/2)+' '+(b.x+NW/2)+','+(b.y-GY/2)+' '+(b.x+NW/2)+','+(b.y-2)+'" fill="none" stroke="#71717A" stroke-width="1.5" marker-end="url(#ah)"/>';
  }
  for(i=0;i<layers.length;i++) for(j=0;j<layers[i].length;j++){
    var n=layers[i][j], p=pos[n], c=cols[i%cols.length];
    s+='<rect x="'+p.x+'" y="'+p.y+'" width="'+NW+'" height="'+NH+'" rx="10" fill="#141417" stroke="'+c+'" stroke-width="1.5"/>';
    s+='<text x="'+(p.x+NW/2)+'" y="'+(p.y+NH/2+5)+'" font-family="system-ui,sans-serif" font-size="14" fill="#FFFFFF" text-anchor="middle">'+archEsc(n)+'</text>';
  }
  return s+'</svg>';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { archParse:archParse, archLayers:archLayers, archSvg:archSvg, archEsc:archEsc };
}
if (typeof window !== 'undefined') {
  window.ArchForgePure = { archParse:archParse, archLayers:archLayers, archSvg:archSvg, archEsc:archEsc };
}
